/*---
description: lt locale casing applies More_Above even when the following accent is a dot
features: [ts-unicode-locale-case, ts-unicode-sequences, ts-strings]
---*/
// Generated by tooling/unicode-cases/locale-case.ts; expected values are from Node.
// Oracle: Unicode 17.0; ICU 78.3.
// docs/foundations/unicode.md: locale-sensitive casing and Staying identical to node.
const input = "\u0049\u0307";
const lower = input.toLocaleLowerCase("\u006c\u0074");
const upper = input.toLocaleUpperCase("\u006c\u0074");
assert.sameValue(lower, "\u0069\u0307\u0307");
assert.sameValue(lower.length, 3);
assert.sameValue(upper, "\u0049\u0307");
assert.sameValue(upper.length, 2);
